toolCalls.args:
{"command":"$i=0; Get-Content .\input\session.jsonl | ForEach-Object {
  $i++
  try { $o = $_ | ConvertFrom-Json } catch { Write-Output ("{0} UNPARSEABLE" -f $i); return }
  $t = $o.type
  if ($t -eq 'response_item') {
    $p = $o.payload
    $pt = $p.type
    if ($pt -eq 'message') { Write-Output ("{0} msg role={1} text={2}" -f $i, $p.role, (($p.content | ForEach-Object { $_.text }) -join ' ').Substring(0, [Math]::Min(200, (($p.content | ForEach-Object { $_.text }) -join ' ').Length))) }
    elseif ($pt -eq 'custom_tool_call') { Write-Output ("{0} CALL {1} input={2}" -f $i, $p.name, $p.input.Substring(0, [Math]::Min(300, $p.input.Length))) }
    elseif ($pt -eq 'custom_tool_call_output') { Write-Output ("{0} RESULT call={1} out={2}" -f $i, $p.call_id, (($p.output | ForEach-Object { $_.text }) -join ' ').Substring(0, [Math]::Min(150, (($p.output | ForEach-Object { $_.text }) -join ' ').Length))) }
    elseif ($pt -eq 'reasoning') { Write-Output ("{0} reasoning (encrypted/summary)" -f $i) }
    else { Write-Output ("{0} resp-item type={1}" -f $i, $pt) }
  } elseif ($t -eq 'event_msg') {
    Write-Output ("{0} event={1}" -f $i, ($o.payload.type))
  } else { Write-Output ("{0} line type={1}" -f $i, $t) }
}"}

{"command":"$lines = Get-Content .\input\session.jsonl
for ($n=0; $n -lt $lines.Count; $n++) {
  $m = [regex]::Matches($lines[$n], '(Slice 3\.2|Resume-first|你现在负责|已完整|handoff|R1|Phase 0 PoC|resumeSummary|Continue)')
  if ($m.Count -gt 0) { Write-Output ("line {0}: hits {1}" -f ($n+1), (($m | ForEach-Object Value) -join ',')) }
}"}

{"command":"$lines = Get-Content .\input\session.jsonl
function Extract-Stdout($lineObj){
  $idx = $lineObj.IndexOf('"stdout":')
  if ($idx -lt 0) { return '' }
  $rest = $lineObj.Substring($idx + 9)
  $end = $rest.IndexOf('","stderr"')
  if ($end -lt 0) { return '' }
  $t = $rest.Substring(0, $end)
  return ($t -replace '\\r\\n', "`n" -replace '\\n', "`n" -replace '\\"', '"' -replace '\\t', "`t")
}
Write-Output '==== LINE 22 (CALL input) ===='; Write-Output $lines[21]
Write-Output '==== LINE 25 stdout ===='; Write-Output (Extract-Stdout $lines[24]).Substring(0, 4000)"}

{"command":"$lines = Get-Content .\input\session.jsonl
function Extract-ResultText($lineObj){
  $idx = $lineObj.IndexOf('"output":')
  $rest = $lineObj.Substring($idx + 9)
  $end = $rest.IndexOf('"internal_chat_message_metadata_passthrough"')
  if ($end -lt 0) { $end = $rest.Length }
  $t = $rest.Substring(0, $end)
  $t = ($t -replace '\\r\\n', "`n" -replace '\\n', "`n" -replace '\\"', '"' -replace '\\t', "`t")
  # strip surrounding JSON array; crude cleanup
  return $t
}
$t = Extract-ResultText $lines[24]
Write-Output $t.Substring(0, [Math]::Min(5000, $t.Length))"}

{"command":"$lines = Get-Content .\input\session.jsonl
foreach ($n in 115,116,117,118,119,120,121,122) {
  $l = $lines[$n]
  $ts = ''
  if ($l -match '"timestamp":"([^"]+)"') { $ts = $Matches[1] }
  Write-Output ("--- line {0} ts={1} len={2} head={3}" -f ($n+1), $ts, $l.Length, $l.Substring(0,[Math]::Min(160,$l.Length)))
}"}

{"command":"$lines = Get-Content .\input\session.jsonl
function Get-ResultText($s) {
  # find output array text fields
  $matches2 = [regex]::Matches($s, '"text":"((?:[^"\\]|\\.)*)"')
  $all = @()
  foreach ($m in $matches2) { $all += $m.Groups[1].Value -replace '\\r\\n', "`n" -replace '\\n', "`n" -replace '\\"', '"' -replace '\\t', "`t" -replace '\\\\', '\' }
  return ($all -join "`n")
}
foreach ($n in 70, 79, 93, 114) {
  Write-Output ("=========== RESULT LINE {0} ===========" -f ($n+1))
  $txt = Get-ResultText $lines[$n]
  Write-Output $txt.Substring(0, [Math]::Min(3500, $txt.Length))
}"}

