{"command":"$lines = Get-Content .\input\session.jsonl
# Show any user-role messages in the whole file (line numbers + snippet)
for ($n=0; $n -lt $lines.Count; $n++) {
  if ($lines[$n] -match '"role":"user"') {
    $m = [regex]::Match($lines[$n], '"text":"([^"\\]{0,400})')
